from pathlib import Path
root=Path(__file__).resolve().parents[1]
path=root/'dist/adventure.js'
s=path.read_text(encoding='utf-8')
s=s.replace('dialogues={rooms:[]},state,actor=', 'dialogues={rooms:[]},extras={rooms:[]},activeSpot=null,state,actor=')
s=s.replace('function render(){activeBeat=null;', 'function render(){activeSpot=null;activeBeat=null;')
s=s.replace('${toolObject()}${npcObject()}', '${toolObject()}${extraObjects()}${npcObject()}')
s=s.replace('<button data-act="help">Hoe werkt dit?</button>', '<div class="exploration-controls"><button data-act="searchSpots" aria-pressed="false">Toon zoekplekken</button><button data-act="help">Hoe werkt dit?</button></div>')
s=s.replace("function npcPosition(){", '''function extraSpots(){return extras.rooms.find(r=>r.room===state.room)?.spots||[];}
function extraObjects(){return extraSpots().map(x=>`<button class="extra-object ${state.exploration[x.id]?'visited':''}" data-act="approachExtra" data-id="${x.id}" aria-label="Onderzoek ${esc(x.title)}" style="--spot-x:${x.point[0]*100}%;left:${x.point[0]*100}%;top:${x.point[1]*100}%"><span class="extra-dot"></span><span class="extra-label">${esc(x.title)}</span></button>`).join('');}
function approachExtra(id){const x=extraSpots().find(x=>x.id===id);if(!x)return;closeTray();walkTo(...x.approach,()=>{activeSpot=x;renderExtra();});speak(`Ik bekijk ${x.title.toLowerCase()}.`,'Jij');}
function renderExtra(feedback='',answered=false){const x=activeSpot;if(!x)return;const locked=x.requires&&(!state.tools.includes(x.requires)||selectedTool!==x.requires||verb!=='use');state.exploration[x.id]=locked?'locked':'visited';persist();document.querySelector(`[data-act="approachExtra"][data-id="${x.id}"]`)?.classList.add('visited');let body=`<p>${esc(x.observation)}</p>`;if(locked){body+=`<div class="tray-hint">Dit serviceslot past op de servicesleutel. Je kunt later terugkomen met het juiste gereedschap.</div>`;}else{if(x.question&&!answered)body+=`<p>${esc(x.question)}</p><div class="puzzle-cards">${x.options.map((o,n)=>button(esc(o.text),'sideAnswer','puzzle-card',`data-index="${n}"`)).join('')}</div>`;if(x.detail)body+=`<div class="reveal-text"><p>${esc(x.detail)}</p></div>`;if(feedback)body+=`<div class="small-feedback ${answered?'':'retry'}">${esc(feedback)}</div>`;if(!x.question||answered)body+=button(state.tools.includes('camera')?'Leg vast met mijn onderzoekscamera':'Noteer dit zijspoor','saveSide','btn-secondary');}body+=button('Verder zoeken','closeTray','btn-primary');tray(x.title,body,'Een spoor onderzoeken');}
function saveSide(){if(!activeSpot)return;const x=activeSpot,text=x.options?.find(o=>o.correct)?.feedback||x.detail||x.observation,entry=`${x.title}: ${x.observation} ${text}`;if(!(state.notes[inv().id]||'').includes(entry)){state.notes[inv().id]=(state.notes[inv().id]||'')+'\\n'+entry;persist();$('#field-notes').value=state.notes[inv().id];}notify('Zijspoor vastgelegd in je onderzoeksboek.');}
function npcPosition(){''')
s=s.replace('approachNPC,closeTray,', "approachNPC,approachExtra:b=>approachExtra(b.dataset.id),sideAnswer:b=>{const o=activeSpot.options[Number(b.dataset.index)];renderExtra(o.feedback,o.correct);},saveSide,searchSpots:b=>{const shown=$('#walk-scene').classList.toggle('show-spots');b.setAttribute('aria-pressed',String(shown));b.textContent=shown?'Verberg zoekplekken':'Toon zoekplekken';},closeTray,")
s=s.replace('[course,campaign,book]=await Promise.all([\'course.json\',\'campaign.json\',\'playbook.json\']', '[course,campaign,book,extras]=await Promise.all([\'course.json\',\'campaign.json\',\'playbook.json\',\'room-extras.json\']')
path.write_text(s,encoding='utf-8')
path=root/'dist/adventure-state.js'
s=path.read_text(encoding='utf-8').replace('expValues:{},finalAnswers:', 'expValues:{},exploration:{},finalAnswers:').replace("objects=['expValues',", "objects=['exploration','expValues',")
path.write_text(s,encoding='utf-8')
with (root/'dist/adventure.css').open('a',encoding='utf-8') as f:
    f.write('''\n.exploration-controls{display:flex;gap:15px}.extra-object{position:absolute;z-index:5;transform:translate(-50%,-50%);width:40px;height:40px;border:0;border-radius:50%;background:transparent;cursor:pointer;color:#f4ead3;padding:0}.extra-dot{display:block;margin:auto;width:7px;height:7px;border-radius:50%;border:1px solid #e7d29b88;background:#17281e66;box-shadow:0 0 8px #e7d29b44;transition:transform .2s}.extra-label{display:none;position:absolute;bottom:100%;left:50%;transform:translateX(-50%);font-size:.6rem;border:1px solid #cfb57d99;border-radius:4px;background:#11271fe8;padding:7px 10px;white-space:nowrap;pointer-events:none}.extra-object:hover .extra-label,.extra-object:focus-visible .extra-label,.show-spots .extra-label{display:block}.extra-object:hover .extra-dot,.extra-object:focus-visible .extra-dot,.show-spots .extra-dot{transform:scale(1.8);background:#f2dc9c}.extra-object.visited .extra-dot{border-color:#a3b892;background:#718360}.show-spots .extra-label{font-size:.52rem;white-space:normal;width:95px;text-align:center}.world-npc{z-index:3}@media(max-width:760px){.extra-object{left:clamp(28px,var(--spot-x,50%),calc(100% - 28px))!important;width:36px;height:36px}.extra-label{white-space:normal;width:85px;font-size:.5rem}.show-spots .extra-label{width:70px;font-size:.46rem}.exploration-controls{gap:10px}}\n''')
path=root/'README.md'
s=path.read_text(encoding='utf-8').replace('The first lesson contains 24 experiential beats,', 'The first lesson contains 30 optional environmental investigations (including evidence checks, dead ends and a services-key return route), 24 experiential beats,')
